import json
n=30
g=[[0]*n for _ in range(n)]
starts=[1,8,15,22,29]
colors=[[3,2,2,3,3],[2,8,8,2,2],[3,2,2,3,3],[2,8,8,2,2],[3,2,2,3,3]]
for ri,r0 in enumerate(starts):
 for ci,c0 in enumerate(starts):
  for dr in range(5):
   for dc in range(5):
    r,c=r0+dr,c0+dc
    if r<n and c<n:
     g[r][c]=4 if dr in (0,4) or dc in (0,4) else colors[ri][ci]
# 3 horizontal links across top and third tile rows, cols 0 to 3
for tr in (0,2):
 for rr in range(starts[tr]+1, starts[tr]+4):
  for c0 in (6,13,20):
   for c in (c0,c0+1): g[rr][c]=3
# 8 horizontal links across tile rows 1,3 between tile cols 1 and 2
for tr in (1,3):
 for rr in range(starts[tr]+1, starts[tr]+4):
  for c in (13,14): g[rr][c]=8
# vertical links 3, tile cols 0 and 3 from tile row 0 to 2
for tc in (0,3):
 for cc in range(starts[tc]+1,starts[tc]+4):
  for r0 in (6,13):
   for r in (r0,r0+1):g[r][cc]=3
# vertical links 8, tile cols 1 and 2 from tile row 1 to 3
for tc in (1,2):
 for cc in range(starts[tc]+1,starts[tc]+4):
  for r0 in (13,20):
   for r in (r0,r0+1):g[r][cc]=8
print(json.dumps(g))
